'use strict';

const logger = require('../logger');
const { ApiError, errorResponse, validationFailed, internalError } = require('../errors');
const { requireSession } = require('../auth');

function parseBody(event) {
    const raw = event && event.body;
    if (raw === undefined || raw === null || raw === '') return null;
    const text = event.isBase64Encoded ? Buffer.from(raw, 'base64').toString('utf8') : raw;
    try {
        return JSON.parse(text);
    } catch (err) {
        throw validationFailed([{ field: 'body', message: 'Request body must be valid JSON' }], 'Request body must be valid JSON');
    }
}

/**
 * Wraps a route handler. fn receives { event, body, session } and returns an API Gateway response.
 * With auth (default) the session is checked before the body is parsed. ApiError becomes its
 * error response; anything else is logged and becomes 500 INTERNAL_ERROR.
 */
function withHandler(fn, { auth = true } = {}) {
    return async (event, context) => {
        try {
            const session = auth ? await requireSession(event) : null;
            const body = parseBody(event);
            return await fn({ event, body, session, context });
        } catch (err) {
            if (err instanceof ApiError) {
                if (err.status >= 500) logger.error('request failed', { code: err.code });
                return errorResponse(err);
            }
            logger.error('unhandled error', {
                errorName: err && err.name,
                errorMessage: err && err.message,
                path: event && event.resource,
                method: event && event.httpMethod,
            });
            return errorResponse(internalError());
        }
    };
}

module.exports = { withHandler, parseBody };
